P=Path(__file__).resolve().parent.parent;O=P/'figs/supplement_review'
r=list(csv.DictReader(io.StringIO(DATA_CSV)))
methods=[('est5','FastSET (Est. 5)','#0072BD','o','-'),('joint','Joint (SP)','#EDB120','D','-.'),('joint_pretrain10','Joint (JP)','#7E2F8E','^','--'),('cnn','E2E','#D95319','s',':')]
fig=plt.figure(figsize=(7.16,2.35));summary=[]
for col,case in enumerate(['A2B','A2C']):
 ax=fig.add_axes([(.50+3.62*col)/7.16,.40/2.35,2.90/7.16,1.45/2.35])
 for index,(m,label,color,mk,ls) in enumerate(methods):
  runs=[sorted([v for v in r if v['scenario']==case and v['method']==m and v['seed']==str(seed) and int(v['iteration'])>0],key=lambda v:int(v['iteration'])) for seed in [42,43,44]]
  for rr in runs:
   for v in rr: assert abs(float(v['ber'])-int(v['errors'])/int(v['bits']))<1e-12
   hit=next(v for v in rr if float(v['ber'])<2e-4)
   summary.append(dict(scenario=case,method=m,label=label,seed=rr[0]['seed'],iteration=int(hit['iteration']),seconds=float(hit['seconds']),ber=float(hit['ber'])))
  xx=np.array([[float(v['seconds']) for v in rr] for rr in runs]);yy=np.array([[float(v['ber']) for v in rr] for rr in runs]);x=xx.mean(axis=0);y=yy.mean(axis=0)
  ax.plot(x,y,color=color,ls=ls,lw=2,marker=mk,ms=4.5,mfc='white',markevery=sorted(set([0,len(x)-1]+list(range(index,len(x),10)))),label=label)
  ax.fill_between(x,yy.min(axis=0),yy.max(axis=0),color=color,alpha=.12,lw=0)
 ax.set(xscale='log',yscale='log',xlabel='Adaptation time (s)',ylabel='BER at 12 dB',ylim=(3e-6,.15),title=case)
 ax.grid(which='major',axis='both',color='#D5D8DC',lw=.5);ax.tick_params(direction='in',pad=2)
 for target in [2e-4,2e-5]:ax.axhline(target,color='#5D6D7E',lw=.8,ls='--' if target==2e-4 else ':')
fig.legend(*fig.axes[0].get_legend_handles_labels(),ncol=4,loc='upper center',bbox_to_anchor=(.51,1.0),frameon=False,handlelength=1.8,handletextpad=.35,columnspacing=.65)
for ext in ['pdf','png','svg']:_save(fig,O/('joint_pretraining_comparison.'+ext),dpi=300,transparent=True,facecolor='none',edgecolor='none')
with (O/'joint_first_hit.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=list(summary[0]));w.writeheader();w.writerows(summary)
table=[r'\begin{tabular}{lrr}',r'\toprule',r'Method & A2B (s) & A2C (s) \\',r'\midrule']
for m,label,*_ in methods:
 vals=[np.mean([v['seconds'] for v in summary if v['scenario']==case and v['method']==m]) for case in ['A2B','A2C']]
 table.append(label+' & '+' & '.join(f'{v:.3f}' for v in vals)+r' \\')
table +=[r'\bottomrule',r'\end{tabular}'];(O/'joint_first_hit.tex').write_text('\n'.join(table)+'\n')
print('\n'.join(table))
